function validatePhotos(photos){if(!Array.isArray(photos)||photos.length>20)throw Error('每案最多20張照片');const ids=new Set();for(const p of photos){if(!p||typeof p.id!=='string'||! /^[a-zA-Z0-9_-]{1,100}$/.test(p.id)||ids.has(p.id))throw Error('照片識別資料不正確');ids.add(p.id);for(const [key,max]of [['name',180],['caption',500],['segmentId',100]])if(typeof p[key]!=='string'||p[key].length>max)throw Error('照片文字資料不正確');if(p.dataUrl!==undefined&&(typeof p.dataUrl!=='string'||p.dataUrl.length>480000||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p.dataUrl)))throw Error('照片格式不正確')}return photos}
function validate(x){if(x?.format!=='sq-field-survey'||x.version!==1||!x.project||!x.conditions||!x.rates||!x.pricing||!Array.isArray(x.segments)||!x.segments.length||x.segments.length>200)throw Error('不是本版勘查資料，或段數超過 200');if(x.caseId!=null&&(typeof x.caseId!=='string'||!/^[a-zA-Z0-9_-]{1,80}$/.test(x.caseId)))throw Error('案件識別碼不正確');if(x.cloudCase!=null){if(!x.cloudCase||typeof x.cloudCase!=='object')throw Error('雲端案件連結不正確');for(const key of ['parentId','folderId','revisionId'])if(typeof x.cloudCase[key]!=='string'||!/^[a-zA-Z0-9_-]{1,100}$/.test(x.cloudCase[key]))throw Error('雲端案件識別碼不正確');}for(const key of ['phone','phone2'])if(x.project[key]!=null&&(typeof x.project[key]!=='string'||x.project[key].length>60))throw Error('電話最多60個字');if(x.railPricing!=null&&!['piece','length'].includes(x.railPricing))throw Error('橫桿計價方式不正確');const segmentIds=new Set();for(const s of x.segments){if(typeof s.id!=='string'||! /^[a-zA-Z0-9_-]{1,100}$/.test(s.id)||segmentIds.has(s.id))throw Error('路段識別資料不正確');segmentIds.add(s.id);if(s.existing!=null&&typeof s.existing!=='boolean')throw Error('既有圍籬設定不正確');if(s.note!=null&&(typeof s.note!=='string'||s.note.length>20000))throw Error('段落備註格式不正確');for(const key of ['postMaterial','gatePostMaterial','gateFrameMaterial'])if(s[key]!=null&&!['galv','zinc','steel','green','black'].includes(s[key]))throw Error('管材選項不正確');for(const key of ['gatePostShape','gateFrameShape'])if(s[key]!=null&&!['round','square'].includes(s[key]))throw Error('大門管形不正確');if(s.gateFinish!=null&&!['none','paint','baked'].includes(s.gateFinish))throw Error('大門顏色選項不正確');if(s.gateFinishColor!=null&&(typeof s.gateFinishColor!=='string'||s.gateFinishColor.length>80))throw Error('顏色最多80字');if(s.gateFoundationNote!=null&&(typeof s.gateFoundationNote!=='string'||s.gateFoundationNote.length>20000))throw Error('基礎工法備註不正確');if(s.gateOpening!=null&&(!Number.isFinite(s.gateOpening)||s.gateOpening<=0||s.gateOpening>5000||s.type==='gate'&&Math.abs(s.length-s.gateOpening-gatePostDiameter(s)/1000)>1e-7))throw Error('大門開口與配置不一致');if(s.meshOnly!=null&&(typeof s.meshOnly!=='boolean'||s.meshOnly&&s.type==='gate'))throw Error('只裝圍網設定不正確');for(const [k,a,b]of [['length',.5,5000],['height',.5,6],['spacing',.5,6],['turn',-180,180],['depth',0,2],['wire',1,6],['mesh',25,150],['railCount',0,4],['postDia',25,200],['angle',0,110]])if(!Number.isFinite(s[k])||s[k]<a||s[k]>b)throw Error(k+' 數值超出範圍');if(!Number.isInteger(s.railCount))throw Error('橫桿排數須為整數');if(s.railLength!=null&&(!Number.isFinite(s.railLength)||s.railLength<.5||s.railLength>12))throw Error('每支橫桿管長須為0.5～12m');if(s.topFix!=null&&!['through','ring'].includes(s.topFix))throw Error('上橫桿固定方式不正確');if(s.slideOpen!=null&&(!Number.isFinite(s.slideOpen)||s.slideOpen<0||s.slideOpen>100))throw Error('推拉開啟須為0～100%');if(s.direction!=null&&![1,-1].includes(s.direction))throw Error('推拉方向不正確');if(s.base!=='plate'&&s.depth<.1)throw Error('埋入工法請選擇至少10公分，無埋入請選底板固定');if(!Number.isFinite(s.postLength)||s.postLength<.5||s.postLength>10||s.postLength<=(s.base==='plate'?0:s.depth))throw Error('立柱總長須為0.5～10m，且大於埋深');if(s.buriedDepth!=null&&(!Number.isFinite(s.buriedDepth)||s.buriedDepth<.1||s.buriedDepth>2))throw Error('暫存埋深不正確');for(const[k,min,max]of [['gatePostDia',25,200],['gatePostThickness',.8,10],['postThickness',.8,10],['railDia',20,150],['railThickness',.8,10]])if(s[k]!=null&&(!Number.isFinite(s[k])||s[k]<min||s[k]>max))throw Error(k+' 規格超出範圍');for(const[k,v]of [['type',['fence','gate']],['base',['plate','buried','direct']],['meshMat',['galv','highgalv','pvc']],['gate',['single','double','sliding']]])if(!v.includes(s[k]))throw Error('規格選項錯誤')}for(const v of [...Object.values(x.rates),...Object.values(x.pricing)])if(!Number.isFinite(v)||v<0||v>1e7)throw Error('金額設定不正確');for(const k of ['excavatorShifts','excavatorRate','excavatorTransport'])if(!Number.isFinite(x.pricing[k])||x.pricing[k]<0||x.pricing[k]>1e7)throw Error('怪手估價數值不正確');if(x.pricing.excavatorShifts>1000)throw Error('怪手台班數上限1000');if(x.pricing.tax>100||String(x.notes).length>20000)throw Error('資料超出範圍');if(x.segments.reduce((n,s)=>n+s.length,0)>20000)throw Error('本測試版單案總長上限 20,000 公尺');validatePhotos(x.photos||[]);return x}
function field(label,key,value,options,min,max,step){return `<label data-field="${key}">${label}${options?`<select data-key="${key}">${options.map(o=>{const[v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`}).join('')}</select>`:`<input data-key="${key}" value="${esc(value)}" type="${min!==undefined?'number':key==='date'?'date':['phone','phone2'].includes(key)?'tel':'text'}" ${min!==undefined?`min="${min}" max="${max}" step="${step||'any'}"`:''}>`}</label>`}
function pipeField(label,key,value,thickness=false){const choices=!thickness&&['postDia','gatePostDia'].includes(key)?[42.7,48.6,60.5,76.3,89.1,101,114].map(v=>[v,v+' mm']):thickness?[[1.4,'1.4 mm 亞管'],[1.8,'1.8 mm 鍍鋅管'],[2,'2 mm'],[2.3,'2.3 mm'],[3.2,'3.2 mm']]:[48.6,60.5,25.4,31.8,34,42.7,76.3,89.1,101,101.6,114].map(v=>[v,v+' mm']);return '<label>'+label+'<select data-pipe="'+key+'"><option value="">待確認</option>'+choices.map(([v,t])=>'<option value="'+v+'" '+(v===value?'selected':'')+'>'+t+'</option>').join('')+'<option value="other" '+(value!=null&&!choices.some(([v])=>v===value)?'selected':'')+'>其他（下方輸入）</option></select></label><div data-custom-field="'+key+'" '+(value!=null&&!choices.some(([v])=>v===value)?'':'hidden')+'>'+field(label+'（自訂 mm）',key,value??'',null,thickness?.8:['postDia','gatePostDia'].includes(key)?25:20,thickness?10:['postDia','gatePostDia'].includes(key)?200:150,.1)+'</div>';}
const gatePipeNames={'zinc-round':'亞圓管','galv-round':'鍍鋅圓管','zinc-square':'亞方管','galv-square':'鍍鋅方管'};
function gatePostDiameter(s){return s.gatePostDia??Math.max(89.1,s.postDia);}
function gateOpeningValue(s){return s.gateOpening??Number((s.length-gatePostDiameter(s)/1000).toFixed(8));}
function setGateOpening(s,value){s.gateOpening=value;s.length=Number((value+gatePostDiameter(s)/1000).toFixed(8));}
function gateKind(s,part){return (part==='post'?(s.gatePostMaterial??s.postMaterial??'zinc'):(s.gateFrameMaterial??s.gatePostMaterial??s.postMaterial??'zinc'))+'-'+(part==='post'?(s.gatePostShape??'round'):(s.gateFrameShape??'round'));}
function gateKindOptions(s,part){const current=gateKind(s,part),keys=part==='post'?['zinc-round','galv-round','zinc-square','galv-square']:['zinc-round','zinc-square','galv-round'];if(!keys.includes(current))keys.push(current);return keys.map(k=>[k,gatePipeNames[k]||'原案管材（保留）']);}
function setGateKind(s,part,value){if(!gatePipeNames[value])throw Error('大門管材選項不正確');const [material,shape]=value.split('-');if(part==='post')s.gateFrameMaterial??=s.gatePostMaterial??s.postMaterial??'zinc';s[part==='post'?'gatePostMaterial':'gateFrameMaterial']=material;s[part==='post'?'gatePostShape':'gateFrameShape']=shape;}
function gatePresetField(label,key,value,values,min,max,step){const custom=value!=null&&!values.includes(value),unit=['height','postLength'].includes(key)?' m':' mm';return '<label>'+label+'<select data-pipe="'+key+'"><option value="">待確認</option>'+values.map(v=>'<option value="'+v+'" '+(value===v?'selected':'')+'>'+v+unit+'</option>').join('')+'<option value="other" '+(custom?'selected':'')+'>其他</option></select></label><div data-custom-field="'+key+'" '+(custom?'':'hidden')+'>'+field(label+'（自訂）',key,value??'',null,min,max,step)+'</div>';}
function componentStyleField(s){const gates=[['gate-single','單開'],['gate-double','雙開'],['gate-sliding','推拉門']],choices=s.type==='gate'?gates:[['fence','管夾式圍籬'],['simple','簡易圍籬（立柱＋菱形網）'],['meshOnly','只裝圍網（既有立柱）'],...gates];return field('構件樣式','componentStyle',s.type==='gate'?'gate-'+s.gate:s.meshOnly?'meshOnly':s.railCount===0?'simple':'fence',choices);}
function siteNoteRows(s=data){return s.segments.flatMap((segment,index)=>[...(segment.type==='gate'&&segment.gateFoundationNote?[{label:'第 '+(index+1)+' 段門柱基礎工法',text:segment.gateFoundationNote}]:[]),...(segment.note?[{label:'第 '+(index+1)+' 段備註',text:segment.note}]:[])]);}
function syncSiteNotes(){const box=$('segmentNotesSummary');if(!box)return;const rows=siteNoteRows();box.hidden=!rows.length;box.innerHTML=rows.length?'<strong>各段備註（自動彙整）</strong>'+rows.map(row=>'<p><b>'+esc(row.label)+'：</b>'+esc(row.text)+'</p>').join(''):'';}
function gateFinishFields(s){return field('顏色','gateFinish',s.gateFinish??'none',[['paint','油漆'],['baked','烤漆'],['none','無']])+'<div data-gate-color '+((s.gateFinish??'none')==='none'?'hidden':'')+'>'+field('自訂顏色／色號','gateFinishColor',s.gateFinishColor??'')+'</div>';}
function gatePostFields(s){return field('門柱管材','gatePostKind',gateKind(s,'post'),gateKindOptions(s,'post'))+pipeField(s.gatePostShape==='square'?'門柱常用邊長':'門柱常用外徑','gatePostDia',gatePostDiameter(s))+gatePresetField('門柱厚度','gatePostThickness',s.gatePostThickness??s.postThickness,[1.4,1.8,2,2.3,3.2],.8,10,.1);}
function postFields(s){if(s.type==='gate')return gatePostFields(s);const gate=s.type==='gate',name=gate?'門柱':'立柱',diaKey=gate?'gatePostDia':'postDia',wallKey=gate?'gatePostThickness':'postThickness',dia=gate?(s.gatePostDia??Math.max(89.1,s.postDia)):s.postDia,wall=gate?(s.gatePostThickness??s.postThickness):s.postThickness,material=gate?(s.gatePostMaterial??s.postMaterial):s.postMaterial;return field(name+'管材','postMaterialPreset',['galv','zinc'].includes(material)?material:wall===1.8?'galv':wall===1.4?'zinc':'custom',[['galv','鍍鋅管（預設 1.8 mm）'],['zinc','錏管／亞管（預設 1.4 mm）'],['custom','自訂厚度']])+pipeField(name+'常用外徑',diaKey,dia)+field(name+'厚度 mm（可自訂）',wallKey,wall??'',null,.8,10,.1);}
function setComponentStyle(s,value){if(value==='gate'||value.startsWith('gate-')){const wasGate=s.type==='gate';s.type='gate';s.meshOnly=false;s.gatePostDia??=Math.max(89.1,s.postDia);s.gatePostMaterial??=s.postMaterial??(s.postThickness===1.4?'zinc':'galv');if(value.startsWith('gate-'))s.gate=value.slice(5);if(wasGate&&s.gateOpening!=null)setGateOpening(s,s.gateOpening);return;}s.type='fence';s.meshOnly=value==='meshOnly';if(value==='simple')s.railCount=0;else if(!s.meshOnly&&s.railCount===0)s.railCount=2;}

function setFoundation(s,base){if(base==='plate'){if(s.depth>0)s.buriedDepth=s.depth;s.depth=0}else if(s.depth===0)s.depth=s.buriedDepth??.5;s.base=base;}
function depthField(s){if(s.base==='plate')return field('埋入深度','depth',0,[[0,'底板固定：不需埋入（0 cm）']]).replace('<select ','<select disabled ');const cm=Number((s.depth*100).toFixed(2)),values=[10,20,25,30,40,50,60,70,80,90,100,120,150,200];if(!values.includes(cm))values.push(cm);return field('埋入深度','depth',cm,values.sort((a,b)=>a-b).map(v=>[v,v+' cm']));}
function blankDesign(){const next=fresh();next.project.name='新圍籬勘查';next.segments=[seg()];return next}
function insertSegment(type='fence',after=data.segments.length-1){if(data.segments.length>=200)throw Error('最多 200 段');const template=(type==='fence'?data.segments.find(s=>s.type==='fence'):data.segments.findLast(s=>s.type==='fence'))||seg();const next={...structuredClone(template),id:seg().id,length:type==='gate'?4:template.length,turn:0,type,existing:false,angle:0,note:'',gate:'double'};if(type==='gate'){next.postDia=Math.max(89.1,next.postDia);next.gatePostDia=89.1;next.gatePostThickness=next.postThickness;next.gatePostMaterial=next.postMaterial??(next.postThickness===1.4?'zinc':'galv');next.gatePostShape='round';next.gateFrameMaterial=next.gatePostMaterial;next.gateFrameShape='round';next.base='buried';next.depth=next.depth>0?next.depth:.5;next.gateFoundationNote='';next.gateFinish='none';next.gateFinishColor='';next.meshOnly=false;setGateOpening(next,4);}data.segments.splice(after+1,0,next);return after+1}
function removeSegment(index){if(data.segments.length<=1)throw Error('至少保留一段，請使用新設計開始另一案');deletedSegment={index,segment:structuredClone(data.segments[index])};data.segments.splice(index,1)}
function restoreSegment(){if(!deletedSegment)return false;if(data.segments.length>=200)throw Error('最多 200 段');data.segments.splice(Math.min(deletedSegment.index,data.segments.length),0,deletedSegment.segment);deletedSegment=null;return true}
function resetScene(){segmentOpen.clear();applied=null;appliedSource='';deletedSegment=null;clearTimeout(previewTimer)}
function backupAndReplace(next){validate(next);localStorage.setItem('sq-field-survey-previous',JSON.stringify(data));data=next;resetScene();render()}
function wireField(s){const values=[2.6,3,3.4,3.9,4,5],custom=!values.includes(s.wire);return field('網線徑 mm','wirePreset',custom?'other':s.wire,[...values,['other','其他／自行輸入']]).replace('<select ','<select data-wire-preset="true" ')+`<div data-wire-custom ${custom?'':'hidden'}>${field('網線徑（自訂 mm）','wire',s.wire,null,1,6,.1)}</div>`;}
function setMeshMaterial(s,value){if(value==='pvc'&&s.meshMat!=='pvc')s.wire=3.9;s.meshMat=value;}
function segmentSpecs(s){
 const gate=s.type==='gate',rails=!gate&&!s.meshOnly&&s.railCount>0;
 const choices=Object.keys(meshOptions).filter(k=>!['2英吋','3英吋'].includes(k));if(!choices.includes(s.meshChoice))choices.push([s.meshChoice,s.meshChoice+'（原案 '+s.mesh+'mm）']);
 const mesh=`<h4 class="fieldGroupTitle">菱形網規格</h4>`+field('網材質','meshMat',s.meshMat,[['galv','鍍鋅'],['highgalv','高鍍鋅'],['pvc','PVC 包覆（綠）']])+wireField(s)+field('網目','meshChoice',s.meshChoice,choices);
 if(s.meshOnly)return mesh+'<p class="hint">沿用既有立柱；只計網子，不新增管材、基礎與管夾。</p>';
 if(gate){const frame=pipeField('管材大小','railDia',s.railDia);return mesh+'<h4 class="fieldGroupTitle">門柱</h4>'+postFields(s)+gatePresetField('門柱管長','postLength',s.postLength,[1.5,2,2.5,3,4,6],.5,10,.01)+field('基礎工法','base',s.base,[...(s.base==='direct'?[['direct','原案工法（保留）']]:[]),['buried','埋入／混凝土'],['plate','底板固定']])+'<label class="full">基礎工法備註<textarea data-key="gateFoundationNote" rows="2" maxlength="20000">'+esc(s.gateFoundationNote??'')+'</textarea></label><h4 class="fieldGroupTitle">門框</h4>'+field('門框種類','gateFrameKind',gateKind(s,'frame'),gateKindOptions(s,'frame'))+frame+gatePresetField('門框厚度','railThickness',s.railThickness,[1.4,1.8,2,2.3,3.2],.8,10,.1)+gateFinishFields(s);}
 const post=`<h4 class="fieldGroupTitle">${gate?'門柱與工法':'立柱與工法'}</h4>`+postFields(s)+field(gate?'門柱總長 m（含埋入）':'立柱總長 m（含埋入）','postLength',s.postLength,null,.5,10,.01)+field('基礎工法','base',s.base,[['buried','埋入／混凝土'],['direct','單獨埋入'],['plate','底板固定']])+depthField(s);
 const rail=gate?'<h4 class="fieldGroupTitle">門框</h4>':rails?'<h4 class="fieldGroupTitle">橫桿</h4>'+field('排數','railCount',s.railCount,[1,2,3,4])+field('管長 m','railLength',s.railLength??3,null,.5,12,.1)+field('上橫桿固定','topFix',s.topFix??'through',[['through','橫通管夾'],['ring','環帽＋連結片']]):'';
 return mesh+post+rail+(gate||rails?pipeField(gate?'門框外徑':'橫桿外徑','railDia',s.railDia)+pipeField(gate?'門框厚度／管種':'橫桿厚度／管種','railThickness',s.railThickness,true):'');
}
