function design(){let heading=0;const nodes=[{x:0,z:0}],edges=[];for(const [i,s]of data.segments.entries()){heading+=s.turn*Math.PI/180;const a=nodes.at(-1);nodes.push({x:a.x+Math.cos(heading)*s.length,z:a.z-Math.sin(heading)*s.length});const {gatePostDia,gatePostThickness,postMaterial,gatePostMaterial,gateOpening,...segment}=s;edges.push({...segment,a:i,b:i+1,style:s.type==='gate'?'gate':'clamp',depth:s.base==='plate'?0:s.depth,postDia:s.type==='gate'?(s.gatePostDia??Math.max(89.1,s.postDia)):s.postDia,postThickness:s.type==='gate'?(s.gatePostThickness??s.postThickness):s.postThickness,thickness:(s.type==='gate'?(s.gatePostThickness??s.postThickness):s.postThickness)??2,postShape:s.type==='gate'?(s.gatePostShape??'round'):'round',railShape:s.type==='gate'?(s.gateFrameShape??'round'):'round',railMaterial:s.type==='gate'?(s.gateFrameMaterial??s.gatePostMaterial??s.postMaterial??'zinc'):s.postMaterial,railDia:s.railDia??30,railThickness:s.railThickness??null,material:(s.type==='gate'?(s.gatePostMaterial??s.postMaterial):s.postMaterial)??((s.type==='gate'?(s.gatePostThickness??s.postThickness):s.postThickness)===1.4?'zinc':'galv'),basePreset:'15',baseSize:15,topFix:s.topFix??'through',meshColor:'green',direction:s.direction??1,slideOpen:s.slideOpen??0,brace:true,gateType:s.gate})}return{format:'sq-fence-design',version:1,railQuantityBasis:'span',name:data.project.name.slice(0,60),nodes,edges,sitePhotoRefs:(data.photos||[]).map(({id,name,caption,segmentId})=>({id,name,caption,segmentId}))}}
function estimate(){let mesh=0,rail=0,total=0,gates=0;const posts=new Map(),d=design();const existing=new Set();for(const [i,s]of data.segments.entries())if(s.existing||s.meshOnly&&s.type==='fence'){const a=d.nodes[i],b=d.nodes[i+1],n=s.type==='gate'?1:Math.ceil((s.length-1e-8)/s.spacing);for(let j=0;j<=n;j++)existing.add((a.x+(b.x-a.x)*j/n).toFixed(4)+','+(a.z+(b.z-a.z)*j/n).toFixed(4));}function add(x,z,s,gate=false){if(s.existing||s.meshOnly&&s.type==='fence')return;const k=x.toFixed(4)+','+z.toFixed(4);if(existing.has(k))return;if(!posts.has(k))posts.set(k,{base:s.base,gate});else if(gate)posts.get(k).gate=true}for(const[i,s]of data.segments.entries()){if(s.existing)continue;total+=s.length;const a=d.nodes[i],b=d.nodes[i+1];add(a.x,a.z,s,s.type==='gate');add(b.x,b.z,s,s.type==='gate');if(s.type==='gate'){gates++;continue}mesh+=s.length;rail+=s.meshOnly?0:s.length*s.railCount;const spans=Math.ceil((s.length-1e-8)/s.spacing);for(let n=1;n<spans;n++)add(a.x+(b.x-a.x)*n/spans,a.z+(b.z-a.z)*n/spans,s)}const plate=[...posts.values()].filter(p=>p.base==='plate').length,direct=[...posts.values()].filter(p=>p.base==='direct').length;return{total,posts:posts.size,mesh,rail,gates,plate,direct,buried:[...posts.values()].filter(p=>p.base!=='plate'&&p.base!=='direct').length,railPieces:globalThis.sqFenceMaterials.railGroups(d,data.segments),accessories:globalThis.sqFenceMaterials.accessoryCount(d)}}
