function lines(){
 const q=estimate(),pipes=q.railPieces,parts=q.accessories.items.filter(p=>p.total>0).map(p=>({key:'part_'+p.key,name:p.name,unit:p.unit,qty:p.total,rate:data.rates['part_'+p.key]??0}));
