   const rails=pipes.length?pipes.map((g,i)=>({key:i===0?'rail':g.rateKey,rateKey:g.rateKey,name:g.name,unit:'支',qty:g.qty,rate:data.rates[g.rateKey]??data.rates.railPiece??0})):[{key:'rail',rateKey:'railPiece',name:'橫桿（無需供料）',unit:'支',qty:0,rate:0}];
   return rails.concat(parts);
  }
