function wholeMeters(n){return Math.ceil(Math.max(0,n-1e-8))}
function quantityText(n){if(Number.isInteger(n))return n.toLocaleString('zh-TW');const whole=Math.floor(n),fraction=n-whole;for(const [v,glyph]of [[.25,'¼'],[.5,'½'],[.75,'¾']])if(Math.abs(fraction-v)<1e-8)return (whole?whole.toLocaleString('zh-TW'):'')+glyph;const digits=String(n).split('.')[1]?.length??0,den=10**digits;let a=Math.round(fraction*den),b=den;while(b){const r=a%b;a=b;b=r}return (whole?whole.toLocaleString('zh-TW')+' ':'')+Math.round(fraction*den/a)+'/'+den/a}
