const fs=require('fs'),path=require('path'),crypto=require('crypto');
const root=__dirname;
const files=['index.html','fence-materials.js','material-test.cjs','quote-units-test.cjs','mesh-presets-test.cjs','height-scale-test.cjs','gate-frame-test.cjs','gate-parameters-test.cjs','studio-output.js','studio-output.css','studio-output-test.cjs','app.js','photos.js','scene-photos.js','scene-photos.css','mobile-view.css','quote-photo-test.cjs','confirmation.js','reference-drawing.js','drive.js','drive-config.js','drive-test.cjs','studio-bridge.js','style.css','studio.html','tools.html','tools.js','tools.json','README.md','AI_README.md','AGENTS.md','HANDOFF.md','test.cjs','build-handoff.cjs','ai.html','.nojekyll','.gitignore'];
const entries=files.map(file=>{const content=fs.readFileSync(path.join(root,file),'utf8');return {path:file,bytes:Buffer.byteLength(content),sha256:crypto.createHash('sha256').update(content).digest('hex'),content};});
// The running site's browser key stays in its existing restricted configuration.
// Handoff exports use a blank template so other AI tools cannot copy that key.
const sourceEntries=entries.map(entry=>{if(entry.path!=='drive-config.js')return entry;const content=entry.content.replace(/apiKey\s*:\s*(['"])[^'"]*\1/,"apiKey:''");return {...entry,configurationTemplate:true,bytes:Buffer.byteLength(content),sha256:crypto.createHash('sha256').update(content).digest('hex'),content};});
fs.writeFileSync(path.join(root,'ai-source.json'),JSON.stringify({format:'sq-fence-source',version:1,files:sourceEntries},null,2)+'\n');
fs.writeFileSync(path.join(root,'ai-manifest.json'),JSON.stringify({format:'sq-fence-source-manifest',version:1,entry:'index.html',handoff:'AI_README.md',source:'ai-source.json',repository:'https://github.com/sq087786789-lgtm/shangching-fence-survey',files:entries.map(({content,...x})=>({...x,url:x.path}))},null,2)+'\n');
console.log('Generated '+entries.length+' source files and SHA-256 manifest');
